    --black:#141414;
    --red:#D0202A;
    --blue:#1E3FA8;
    --yellow:#F2C500;
    --line:9px;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  ::selection{background:var(--yellow);color:var(--black)}
  html{scroll-behavior:smooth}
  body{
    font-family:"Archivo",sans-serif;
    background:var(--white);
    color:var(--black);
    line-height:1.5;
  }
  a{color:inherit}

  /* the page as a Mondrian grid: thick black rules dividing white fields */
  .page{
    max-width:1200px;
    margin:0 auto;
    border-left:var(--line) solid var(--black);
    border-right:var(--line) solid var(--black);
    border-bottom:var(--line) solid var(--black);
  }

  /* ---------- hero: the picture itself ---------- */
  .hero{
    display:grid;
    grid-template-columns:38% 34% 28%;
    grid-template-rows:58vh 42vh;
    border-top:var(--line) solid var(--black);
  }
  .hero > div{position:relative}
  .hero .red{
    grid-column:2 / 4;grid-row:1;
    background:var(--red);
    border-left:var(--line) solid var(--black);
    border-bottom:var(--line) solid var(--black);
  }
  .hero .white-top{
    grid-column:1;grid-row:1;
    border-bottom:var(--line) solid var(--black);
  }
  .hero .white-left{
    grid-column:1;grid-row:2;
    border-right:var(--line) solid var(--black);
  }
  .hero .blue{
    grid-column:2;grid-row:2;
    background:var(--blue);
  }
  .hero .yellow{
    grid-column:3;grid-row:2;
    background:var(--yellow);
    border-left:var(--line) solid var(--black);
  }
  .hero h1{
    position:absolute;
    left:2rem;top:2rem;
    font-weight:900;
    font-size:clamp(1.4rem,3.2vw,2.6rem);
    line-height:1.05;
    max-width:12ch;
    letter-spacing:-0.02em;
  }
  .hero .plate{
    position:absolute;
    left:2rem;bottom:2rem;
    font-weight:500;
    font-size:0.95rem;
  }
  .hero .plate b{display:block;font-weight:700}

  /* ---------- sections divided by full rules ---------- */
  section{border-top:var(--line) solid var(--black);padding:4.5rem 2rem}
  section h2{
    font-weight:900;
    font-size:clamp(1.6rem,3.5vw,2.4rem);
    letter-spacing:-0.02em;
    margin-bottom:1.2rem;
    line-height:1.1;
  }
  section p{max-width:62ch;font-size:1.05rem}
  section p + p{margin-top:1rem}

  .cols{
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:2rem;
  }

  /* De Stijl principles rendered as colour chips in a ruled strip */
  .principles{
    margin-top:2.5rem;
    display:grid;
    grid-template-columns:repeat(3,1fr) 1.6fr;
    border:var(--line) solid var(--black);
  }
  .principles div{
    padding:1.2rem 1rem;
    font-weight:700;
    font-size:0.95rem;
  }
  .principles .c-red{background:var(--red);color:#fff}
  .principles .c-blue{background:var(--blue);color:#fff}
  .principles .c-yellow{background:var(--yellow);color:var(--black)}
  .principles .c-non{background:#fff;border-left:var(--line) solid var(--black)}

